package yagen.waitmydawn.kb.service;

import com.fasterxml.jackson.databind.JsonNode;
import yagen.waitmydawn.kb.renderer.CardFont;
import yagen.waitmydawn.kb.renderer.MinecraftSlot;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.math.*;
import java.util.*;
import java.util.List;

/** 概率仅针对单次池抽取；动态条件或非标准竞争条目保持未知。 */
final class ChestLootRenderer {
    record Slot(JsonNode rule,String id,String count,Double probability){}
    record Pool(JsonNode rule,List<Slot> slots){}
    static String number(JsonNode value){if(value.isNumber())return new BigDecimal(value.asText()).stripTrailingZeros().toPlainString();if(value.path("type").asText().equals("minecraft:uniform"))return number(value.path("min"))+"-"+number(value.path("max"));return "动态";}
    static String placeholder(JsonNode entry){return entry.path("type").asText().equals("minecraft:empty")?"空":entry.path("type").asText().equals("minecraft:loot_table")?"引用表":"未知";}
    static String quantity(JsonNode entry){if(entry.path("type").asText().equals("minecraft:empty"))return "—";String count="1";for(var f:entry.path("functions")){String type=f.path("function").asText();if(f.path("conditions").size()>0){count="动态";continue;}if(type.equals("minecraft:set_count")&&!f.path("add").asBoolean()){count=number(f.path("count"));}else if(!Set.of("minecraft:set_damage","minecraft:enchant_randomly","minecraft:enchant_with_levels","minecraft:set_name","minecraft:set_lore","minecraft:set_attributes","minecraft:set_nbt","minecraft:set_components").contains(type))count="动态";}return count;}
    static Double gate(JsonNode conditions){double chance=1;for(var c:conditions){if(!c.path("condition").asText().equals("minecraft:random_chance")||!c.path("chance").isNumber())return null;double p=c.path("chance").asDouble();if(p<0||p>1)return null;chance*=p;}return chance;}
    static List<Pool> pools(JsonNode definition){var pools=new ArrayList<Pool>();for(var p:definition.path("pools")){double sum=0;boolean exact=true;for(var e:p.path("entries")){int weight=e.path("weight").asInt(1);sum+=Math.max(0,weight);if((e.path("conditions").size()>0&&(p.path("entries").size()!=1||gate(e.path("conditions"))==null))||e.path("quality").asInt()!=0||e.has("children")||!Set.of("minecraft:item","minecraft:empty","minecraft:loot_table").contains(e.path("type").asText()))exact=false;}
        Double gate=gate(p.path("conditions"));var slots=new ArrayList<Slot>();for(var e:p.path("entries")){String id=e.path("name").asText(e.path("value").asText(e.path("type").asText("未知条目")));Double probability=exact&&gate!=null&&sum>0?Math.max(0,e.path("weight").asInt(1))/sum*gate*(p.path("entries").size()==1?gate(e.path("conditions")):1):null;var effective=((com.fasterxml.jackson.databind.node.ObjectNode)e).deepCopy();var functions=com.fasterxml.jackson.databind.node.JsonNodeFactory.instance.arrayNode();e.path("functions").forEach(functions::add);p.path("functions").forEach(functions::add);definition.path("functions").forEach(functions::add);effective.set("functions",functions);slots.add(new Slot(e,id,quantity(effective),probability));}pools.add(new Pool(p,List.copyOf(slots)));}return pools;}
    static String percent(Double value){if(value==null)return "?";if(value==1)return "100%";String text=BigDecimal.valueOf(value*100).round(new MathContext(2,RoundingMode.HALF_UP)).toPlainString();return (value<1&&text.equals("100")?"≈":"")+text+"%";}
    static Color probabilityColor(Double p,List<Slot> slots){if(p==null)return Color.LIGHT_GRAY;var values=slots.stream().map(Slot::probability).filter(Objects::nonNull).distinct().sorted().toList();if(values.size()==1)return new Color(0x55ffff);if(p.equals(values.getFirst()))return new Color(0xff55ff);if(p.equals(values.getLast()))return new Color(0xffff55);return new Color(0x55ffff);}
    static int fontSize(Graphics2D g,List<Pool> pools){int size=28;for(var pool:pools)for(var slot:pool.slots())for(String text:List.of(percent(slot.probability()),slot.count())){int fits=28;while(fits>1&&g.getFontMetrics(CardFont.at(Font.BOLD,fits)).stringWidth(text)>92)fits--;size=Math.min(size,fits);}return size;}
    static String describe(JsonNode rules){var parts=new ArrayList<String>();for(var r:rules){String type=r.path("function").asText(r.path("condition").asText("未知规则"));parts.add(switch(type){case "minecraft:set_count"->(r.path("add").asBoolean()?"增加数量 ":"设置数量 ")+number(r.path("count"));case "minecraft:random_chance"->"触发概率 "+(r.path("chance").isNumber()?percent(r.path("chance").asDouble()):"动态");case "minecraft:killed_by_player"->"需要玩家击杀";case "minecraft:enchant_randomly"->"随机附魔（候选限制见JSON）";case "minecraft:enchant_with_levels"->"按等级附魔 "+number(r.path("levels"));case "minecraft:match_tool"->"工具限制（见JSON）";case "minecraft:survives_explosion"->"需要通过爆炸存活判定";default->type+"（参数见JSON）";});}return String.join("；",parts);}
    private static void shadow(Graphics2D g,String text,int x,int y,Color color){g.setColor(new Color(0x303030));g.drawString(text,x+2,y+2);g.setColor(color);g.drawString(text,x,y);}
    static BufferedImage render(String id,String profile,JsonNode definition,ItemIconService.Snapshot icons){
        var pools=pools(definition);var details=new ArrayList<String>();int height=150;
        for(int i=0;i<pools.size();i++){var pool=pools.get(i);height+=70+((pool.slots().size()+8)/9)*108;details.add("池 "+(i+1)+" · 抽取次数 "+number(pool.rule().path("rolls"))+" · 额外抽取 "+(pool.rule().has("bonus_rolls")?number(pool.rule().path("bonus_rolls")):"0"));for(int j=0;j<pool.slots().size();j++){var s=pool.slots().get(j);String name=s.rule().path("type").asText().equals("minecraft:item")?icons.item(s.id(),false,null).name():placeholder(s.rule());details.add("池"+(i+1)+" / 格"+(j+1)+"  "+name+" · "+s.id());details.add("  数量 "+s.count()+"；单次抽取概率 "+percent(s.probability())+"；权重 "+s.rule().path("weight").asInt(1));if(s.rule().has("conditions"))details.add("  条目条件："+describe(s.rule().path("conditions")));if(s.rule().has("functions"))details.add("  数量/效果规则："+describe(s.rule().path("functions")));}if(pool.rule().has("conditions"))details.add("  池条件："+describe(pool.rule().path("conditions")));if(pool.rule().has("functions"))details.add("  池函数："+describe(pool.rule().path("functions")));}
        if(definition.has("functions"))details.add("全表函数："+describe(definition.path("functions")));
        if(pools.isEmpty())details.add("没有标准战利品池；请在目录查看原始规则及修饰器。");
        var wrapped=new ArrayList<String>();for(String line:details)for(int a=0;a<Math.max(1,line.length());a+=76)wrapped.add(line.substring(a,Math.min(line.length(),a+76)));
        boolean truncated=height+wrapped.size()*25>25000;int allowed=Math.max(0,(25000-height)/25);if(wrapped.size()>allowed)wrapped=new ArrayList<>(wrapped.subList(0,allowed));height+=wrapped.size()*25+75;if(height>26000)throw new IllegalArgumentException("战利品池过多，请按表拆分审阅");
        var image=new BufferedImage(1100,height,2);var g=image.createGraphics();try{g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,RenderingHints.VALUE_TEXT_ANTIALIAS_ON);g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);g.setColor(new Color(0xf4f5f7));g.fillRect(0,0,1100,height);g.setColor(new Color(0x202a38));g.setFont(CardFont.at(Font.BOLD,23));g.drawString("战利品表 · "+id,24,35);g.setFont(CardFont.at(Font.PLAIN,16));g.drawString("快照："+profile,24,64);g.drawString("概率为每次抽取的机会，非多次抽取的最终获得率；? 表示条件、嵌套条目或动态规则无法静态换算。",24,91);
            int font=fontSize(g,pools),y=120;for(int i=0;i<pools.size();i++){var p=pools.get(i);g.setColor(new Color(0x6b4c32));g.fillRect(20,y,1060,48);g.setColor(Color.WHITE);g.setFont(CardFont.at(Font.BOLD,20));g.drawString("战利品池"+(i+1)+"  抽取次数:"+number(p.rule().path("rolls"))+"  额外抽取:"+(p.rule().has("bonus_rolls")?number(p.rule().path("bonus_rolls")):"0"),32,y+31);y+=60;
                for(int j=0;j<p.slots().size();j++){var slot=p.slots().get(j);int x=24+(j%9)*108,sy=y+(j/9)*108;MinecraftSlot.draw(g,x,sy,6);if(slot.rule().path("type").asText().equals("minecraft:item")){var icon=icons.item(slot.id(),false,null);if(icon.image()!=null)g.drawImage(icon.image(),x+6,sy+6,96,96,null);else{g.setColor(Color.WHITE);g.drawString("?",x+48,sy+67);}}else{g.setColor(Color.WHITE);g.setFont(CardFont.at(Font.BOLD,23));String label=placeholder(slot.rule());g.drawString(label,x+(108-g.getFontMetrics().stringWidth(label))/2,sy+65);}g.setFont(CardFont.at(Font.BOLD,font));shadow(g,percent(slot.probability()),x+8,sy+font+6,probabilityColor(slot.probability(),p.slots()));String count=slot.rule().path("type").asText().equals("minecraft:empty")?"":slot.count();shadow(g,count,x+100-g.getFontMetrics().stringWidth(count),sy+99,Color.WHITE);}
                y+=((p.slots().size()+8)/9)*108+10;
            }g.setColor(new Color(0x202a38));g.setFont(CardFont.at(Font.PLAIN,18));for(String line:wrapped){g.drawString(line,24,y+22);y+=25;}if(truncated)g.drawString("说明已截断，完整规则请在目录中查看。",24,y+35);
        }finally{g.dispose();}return image;
    }
}
